+/* Allocate + fill a deterministic buffer of the given size */
+static unsigned char* make_buf(size_t size)
+{
+    unsigned char* buf = (unsigned char*)malloc(size);
+    size_t         i;
+    if (!buf) return NULL;
+    for (i = 0; i < size; i++) {
+        buf[i] = (unsigned char)(i ^ (i >> 8));
+    }
+    return buf;
+}
+
+#define SEED1     0x0ULL
